arguments.new_str:
protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: Cosmos DB indexes are managed via the container's indexing policy,
    // not EF Core. EF Core 9 throws if HasIndex is used with the Cosmos provider.

    // Preserve the EF Core 8 discriminator property name so existing documents
    // with "Discriminator": "Blog" and raw SQL queries filtering on c.Discriminator
    // continue to work.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve the EF Core 8 compound id format ("Blog|1") so existing documents
    // remain accessible via FindAsync and point-reads.
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);
}

